create extension if not exists "pgcrypto";
create type user_role as enum ('customer','business_member','installer','admin');
create type user_status as enum ('pending','active','rejected','suspended');
create table if not exists users (id uuid primary key default gen_random_uuid(), email text unique, phone text, role user_role not null default 'customer', status user_status not null default 'pending', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists product_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, parent_id uuid references product_categories(id), sort_order int default 0, is_active bool default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists product_brands (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, is_primary bool default false, is_active bool default true, created_at timestamptz default now(), updated_at timestamptz default now());
create type stock_status as enum ('unknown','in_stock','low_stock','out_of_stock');
create table if not exists products (id uuid primary key default gen_random_uuid(), category_id uuid references product_categories(id), brand_id uuid references product_brands(id), name text not null, slug text unique not null, model_name text, short_description text, detailed_description text, capacity text, heating_area text, fuel_type text, installation_type text, public_price numeric not null default 0, business_price numeric not null default 0, smartstore_url text, images text[] default '{}', tags text[] default '{}', stock_quantity int, stock_status stock_status default 'unknown', is_active bool default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists installation_requests (id uuid primary key default gen_random_uuid(), tracking_code text unique not null, customer_name text not null, phone text not null, address text not null, detailed_address text, region text, purchase_source text default 'unknown', smartstore_order_number text, existing_boiler_brand text, existing_boiler_model text, home_size text, flue_type text, site_photo_urls text[] default '{}', notes text, status text default '설치중개 신청됨', privacy_consent bool not null default true, marketing_consent bool default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists bulk_quote_requests (id uuid primary key default gen_random_uuid(), requester_type text not null, customer_name text not null, company_name text, phone text not null, email text, desired_products jsonb default '[]'::jsonb, quantity int default 1, message text, status text default 'submitted', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists notification_logs (id uuid primary key default gen_random_uuid(), recipient_name text, recipient_phone text, channel text, template_key text, message text, status text default 'created', related_type text, related_id uuid, created_at timestamptz default now());
alter table products enable row level security;
create policy "public read active products" on products for select using (is_active = true);
alter table installation_requests enable row level security;
create policy "public insert installation request" on installation_requests for insert with check (true);
